function validate([strs]) {
  if (!Array.isArray(strs) || strs.length < 1 || strs.length > 100) return 'strs needs 1 to 100 strings.';
  const m = strs[0].length;
  if (m < 1 || m > 100) return 'Each string has 1 to 100 characters.';
  for (const s of strs) {
    if (s.length !== m) return 'All strings must have the same length.';
    if (!/^[a-z]+$/.test(s)) return 'Strings use only lowercase English letters.';
  }
  return null;
}

