function minDeletionSize(strs) {
  const cols = strs[0].length;
  const dp = new Array(cols).fill(1);
  let longest = 1;
  for (let j = 1; j < cols; j++) {
    for (let i = 0; i < j; i++) {
      let fits = true;
      for (const row of strs) {
        if (row[i] > row[j]) {
          fits = false;
          break;
        }
      }
      if (fits && dp[i] + 1 > dp[j]) {
        dp[j] = dp[i] + 1;
      }
    }
    longest = Math.max(longest, dp[j]);
  }
  return cols - longest;
}

