function minDeletionSize(strs) {
  // Top-down search: at each column either skip it or keep it if it fits after the last kept column.
  const m = strs[0].length;
  const memo = new Map();
  const canFollow = (a, b) => a < 0 || strs.every(s => s[a] <= s[b]);
  const keep = (c, last) => {
    if (c === m) return 0;
    const key = c * 128 + (last + 1);
    if (memo.has(key)) return memo.get(key);
    let best = keep(c + 1, last);
    if (canFollow(last, c)) best = Math.max(best, 1 + keep(c + 1, c));
    memo.set(key, best);
    return best;
  };
  return m - keep(0, -1);
}

