function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 4);
    const m = 1 + Math.floor(rand() * 9);
    const k = 2 + Math.floor(rand() * 4);
    const strs = [];
    for (let r = 0; r < n; r++) {
      let s = '';
      for (let c = 0; c < m; c++) s += letters[Math.floor(rand() * k)];
      strs.push(s);
    }
    return [strs];
  }
  // Large: mostly sorted rows with a shared set of scrambled columns, so the answer is neither 0 nor m - 1.
  const n = 20 + Math.floor(rand() * 81);
  const m = 60 + Math.floor(rand() * 41);
  const noisy = Array.from({ length: m }, () => rand() < 0.35);
  const strs = [];
  for (let r = 0; r < n; r++) {
    const sorted = Array.from({ length: m }, () => Math.floor(rand() * 26)).sort((a, b) => a - b);
    let s = '';
    for (let c = 0; c < m; c++) s += letters[noisy[c] ? Math.floor(rand() * 26) : sorted[c]];
    strs.push(s);
  }
  return [strs];
}
